window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[33]={"id":"033","numero":33,"titre":"Allaitement maternel","objectifs":[{"id":"33-1","rang":"A","rubrique":"Prise en charge","titre":"Connaître les bénéfices de l’allaitement maternel","contenu":"<div class=\"notion-course\"><p>Le <span><span class=\"nc-pink nc-bold\">lait maternel</span> (LM)</span> est le <strong>lait le plus adapté</strong> à la croissance et au développement du nourrisson. Sa composition est <strong>variable</strong> (selon le <span>stade</span> de lactation, le terme, l’âge, le nycthémère, voire le moment de la tétée), constamment ajustée aux besoins physiologiques. Il a <strong><span <span=\"\">&gt;2</span> grandes fonctions</strong> chez l’enfant : <span>nutritive</span> et <span>immunologique</span>.</p>\n\n      <h4>Composition du <span class=\"nc-pink nc-bold\">lait maternel</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Éléments</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Éléments nutritifs</strong></td>\n            <td>\n              <ul>\n                <li>Eau, oligoéléments</li>\n                <li><span><span class=\"nc-pink_bg\">Lactose</span></span>, <span class=\"nc-pink_bg\">protéines solubles</span> (α-lactoglobulines)</li>\n                <li><span>AGE</span> (acide linoléique, α-linolénique), <span><span class=\"nc-pink_bg\">triglycérides</span></span><span class=\"nc-pink_bg\"> à chaîne longue</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Éléments non nutritifs</strong><br><em>(rôle immunologique = immunité passive)</em></td>\n            <td>\n              <ul>\n                <li>Protéines essentielles : <span><span class=\"nc-blue_bg\">lysozyme</span></span>, <span><span class=\"nc-blue_bg\">immunoglobulines</span></span>, <span><span class=\"nc-blue_bg\">lactoferrine</span></span></li>\n                <li>Éléments cellulaires : <span><span class=\"nc-blue_bg\">lymphocytes</span></span>, <span><span class=\"nc-blue_bg\">polynucléaires</span></span>, <span class=\"nc-blue_bg\">macrophages</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Teneur basse</strong> <em>(à supplémenter)</em></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Caséine</span></span> (protéine à digestion lente)</li>\n                <li><span>Vitamine D</span>, <span>Vitamine K</span>, <span>Fer</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Alimentation maternelle</strong></td>\n            <td>Peu d’impact sur la composition du LM, <em>sauf</em> teneur en : graisses (AG polyinsaturés), iode, sélénium, vitamines A et B</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Variations dans les 1ers jours d’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th><span>Stade</span></th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-green nc-bold\">Colostrum</span></strong><br><em>(1ers allaitements)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Couleur </span><strong><span class=\"nc-yellow_bg\">orangée</span></strong></li>\n                <li><span><span class=\"nc-red nc-bold\">Pauvre en graisses</span></span></li>\n                <li><span class=\"nc-green_bg\">Riche en </span><span><span class=\"nc-green_bg\">IgA</span></span>, <span class=\"nc-green_bg\">glycoprotéines</span>, <span class=\"nc-green_bg\">oligosaccharides</span>, <span class=\"nc-green_bg\">cellules</span> <span class=\"nc-green_bg\">immunitaires</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span>J15</span></strong></td>\n            <td><span class=\"nc-green_bg\">Lait de plus en plus </span><strong><span class=\"nc-green_bg\">riche en</span> <span class=\"nc-green_bg nc-bold\">graisses</span></strong> <em>(rôle dans la maturation cérébrale et rétinienne)</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Comparaison <span class=\"nc-pink nc-bold\">lait maternel</span> <em><span>vs</span></em> lait de vache</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Particularité du LM</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Protéines</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-red_bg\">Plus pauvre en caséines</span></strong> (explique sa couleur translucide)</li>\n                <li><span class=\"nc-green_bg\">Plus riche en protéines non nutritives</span> (<span class=\"nc-green_bg\">lactoferrine</span>, Ig, <span class=\"nc-blue_bg\">lysozyme</span>) → mieux adapté à un nouveau-né au système immunitaire immature</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td><span class=\"nc-red_bg\">Moins riche en </span><span><span class=\"nc-red_bg\">vitamine D</span></span> → source de <span><span class=\"nc-orange nc-bold\">rachitisme</span></span> (intérêt d’une <strong>supplémentation systématique</strong>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bénéfices chez la mère</h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Bénéfice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cancer</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Diminution du cancer de l’</span><span><span class=\"nc-red_bg nc-bold\">ovaire</span></span> : <span>−8 %</span> du risque épithélial dès <span>5 mois</span> d’AM</li>\n                <li><span class=\"nc-red_bg\">Diminution du cancer du</span> <span><span class=\"nc-red_bg nc-bold\">sein</span></span> : <span>−4 %</span>/an d’AM, encore plus marqué si <strong>BRCA1</strong> (<span>−40 %</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vasculaire</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-green_bg\">Perte de poids</span></span><span class=\"nc-green_bg\"> / diminution de la </span><span><span class=\"nc-green_bg\">masse</span></span><span class=\"nc-green_bg\"> grasse plus rapides en post-partum</span></li>\n                <li>Diminution de : <strong><span><span class=\"nc-orange nc-bold\">obésité</span></span></strong>, <strong><span><span class=\"nc-orange nc-bold\">DT2</span></span></strong>, <strong><span class=\"nc-orange nc-bold\">dyslipidémies</span></strong>, <strong><span><span class=\"nc-orange nc-bold\">HTA</span></span></strong>, <strong><span class=\"nc-orange nc-bold\">maladie</span> <span>CV</span></strong> <em>(bénéfice persistant après ménopause)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychique</strong></td>\n            <td>\n              <ul>\n                <li>Diminution de la fréquence de la <span><span class=\"nc-orange nc-bold\">dépression du post-partum</span></span></li>\n                <li><span class=\"nc-green_bg\">Diminue la réponse au stress</span>, améliore le bien-être et l’estime de soi</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              <ul>\n                <li>Favorise le <strong>lien mère/enfant</strong></li>\n                <li>Avantage financier (meilleure protection contre la dénutrition dans les pays en voie de développement)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bénéfices chez l’enfant</h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Bénéfice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Principal +++</strong></td>\n            <td><span>Diminution des infections pédiatriques</span> : <strong>ORL</strong>, <strong>gastroentérite</strong>, <strong>respiratoire</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pathologies réduites</strong></td>\n            <td>\n              <ul>\n                <li>Allergies : <strong><span><span class=\"nc-orange nc-bold\">eczéma</span></span></strong> chez le &lt;<span> 2 ans</span>, <strong><span class=\"nc-orange nc-bold\">rhinite </span><span><span class=\"nc-orange nc-bold\">allergique</span></span></strong> chez le &lt;<span> 5 ans</span>, <strong><span><span class=\"nc-orange nc-bold\">asthme</span></span></strong> entre <span>5–18 ans</span></li>\n                <li>Leucémies pédiatriques : <span>−20 %</span> dès <span>6 mois</span> d’AM</li>\n                <li>Risque de <strong><span class=\"nc-orange nc-bold\">malocclusion dentaire</span></strong></li>\n                <li>Probable <span>réduction</span> du risque d’<strong><span><span class=\"nc-orange nc-bold\">obésité</span></span></strong> et de <strong><span><span class=\"nc-orange nc-bold\">diabète</span></span></strong></li>\n                <li><span><span class=\"nc-red_bg nc-bold\">Mort subite du nourrisson</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Intelligence</strong></td>\n            <td>Gain de QI <span>+3</span></td>\n          </tr>\n          <tr>\n            <td><strong>Spécifique du prématuré</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Améliore la tolérance digestive et le développement cognitif</span></li>\n                <li><span class=\"nc-red_bg\">Réduit le risque d’</span><span><span class=\"nc-red_bg nc-bold\">ECUN</span></span> (entérocolite ulcéro-nécrosante)</li>\n                <li>Modalités possibles : sein, tasse, pipette, cuillère, SNG, ou <strong>lait de <span class=\"nc-pink nc-bold\">Lactarium</span></strong> <em>(centre de collecte de lait de donneuses bénévoles pour prématurés et nv-né de faible poids de <span class=\"nc-pink_bg nc-bold\">naissance</span>)</em></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> Les <strong>modifications de l’aspect esthétique des seins</strong> sont plus liées <strong>à la <span>grossesse</span> elle-même</strong> qu’à l’<span>allaitement</span>. C’est un argument fréquemment opposé à l’AM qu’il faut savoir corriger.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 47 — <span>Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 69 — Trouble psy <span>grossesse</span> - postpartum</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li></ul></details>","frequence":0},{"id":"33-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence, les facteurs influençant l’allaitement","contenu":"<div class=\"notion-course\"><h4><span>Épidémiologie</span> — chiffres clés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Donnée</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Géographie</strong></td>\n            <td>\n              <ul>\n                <li><span>Prévalence</span> et durée de l’AM en France sont <strong>parmi les plus faibles d’Europe</strong></li>\n                <li>Régions où la <span>prévalence</span> <span class=\"nc-green_bg\">est</span> plus élevée : <span class=\"nc-green_bg\">Île-de-France</span>, <span class=\"nc-green_bg\">Est</span>, <span class=\"nc-green_bg\">départements d’outre-mer</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Prévalence</span></strong></td>\n            <td>\n              <ul>\n                <li>En maternité : <span>70 %</span> (<span>60 %</span> exclusif,<span> 10 %</span> partiel)</li>\n                <li>À <span>3 mois</span> : <span>40 %</span></li>\n                <li>À <span>6 mois</span> : <span>&lt; 20 %</span> <em>(ancien réf :<span> 10 %</span> à<span> 1 an</span>)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>\n              <ul>\n                <li>Durée médiane (ancien réf) : <span>15 semaines</span> (dont 24 j exclusifs)</li>\n                <li>Durée idéale recommandée : <span><span class=\"nc-green nc-bold\">4 à 6 mois</span></span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs favorisant l’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Terrain</span></strong></td>\n            <td>\n              <ul>\n                <li>Femme âgée, diplômée, <span class=\"nc-blue_bg\">profession qualifiée</span>, <strong>primipare</strong></li>\n                <li><strong>Soutien</strong> de l’entourage, prise de décision d’AM <strong>avant la <span>grossesse</span></strong></li>\n                <li>Accouchement dans une maternité labellisée <span>IHAB</span> (Initiative Hôpital Ami des Bébés)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Promotion</strong></td>\n            <td>\n              <ul>\n                <li>Promotion de l’AM = objectif du <strong>Programme National Nutrition Santé (PNNS)</strong></li>\n                <li><strong>Code du travail</strong> : pauses sur le temps de travail, lieux appropriés pour exprimer le lait, horaires souples</li>\n                <li>Implication des <strong>pédiatres</strong> doit être exemplaire</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Facteurs de risque</span> d’arrêt prématuré <span>(5 catégories)</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li>Jeune, primipare, célibataire, faible statut socio-économique, mère récemment immigrée</li>\n                <li>Décision tardive d’allaiter, 1<sup>ère</sup> expérience d’<span>allaitement</span>, expérience passée négative</li>\n                <li><span><span class=\"nc-red nc-bold\">Utilisation précoce d’une tétine</span></span>, <span><span class=\"nc-red_bg\">tabagisme</span></span>, <span><span class=\"nc-red_bg\">obésité</span></span>, <span class=\"nc-red_bg\">exercice d’une profession</span></li>\n                <li><span class=\"nc-red_bg\">Manque de confiance</span>, incertitude sur la quantité de lait prise, <span class=\"nc-red_bg\">perception d’une insuffisance de lait</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bébé</strong></td>\n            <td>\n              <ul>\n                <li><span>Perte de poids</span> <span>&gt; 10 %</span></li>\n                <li><span class=\"nc-red_bg\">Faible prise de poids</span></li>\n                <li><span class=\"nc-red_bg\">Problèmes de succion</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Entourage</strong></td>\n            <td>\n              <ul>\n                <li>Absence de soutien du partenaire</li>\n                <li>Perception négative du père</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Organisation en maternité</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Mise au sein différée</span>, 1<sup>er</sup> peau à peau retardé</li>\n                <li>Méconnaissance et manque de soutien des professionnels</li>\n                <li><span>Allaitement</span> à horaires fixes</li>\n                <li><span><span class=\"nc-red nc-bold\">Recours aux compléments de lait artificiel en maternité</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Politiques</strong></td>\n            <td>Congé de maternité court et peu rémunéré</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 47 — <span>Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li></ul></details>","frequence":0},{"id":"33-3","rang":"A","rubrique":"Prise en charge","titre":"Savoir expliquer les modalité pratiques de l’allaitement maternel","contenu":"<div class=\"notion-course\"><h4>Conseils pour l’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Conseil</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>ère</sup> tétée</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Mise au sein </span><strong><span class=\"nc-green_bg\">immédiate</span></strong>, <span class=\"nc-green_bg\">si possible en salle de travail</span></li>\n                <li>Délai : sans précipitation, mais <span><span class=\"nc-pink nc-bold\">&lt; 30 min</span></span> après la naissance</li>\n                <li>Colostrum riche en Ig → favorise la <strong>montée laiteuse</strong> ; réflexe de succion à son maximum</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Mère assise ou couchée</span></li>\n                <li><span class=\"nc-blue_bg\">Donner les 2 seins à chaque tétée</span> <em>(alterner → diminue les complications)</em></li>\n                <li><span class=\"nc-yellow_bg\">Bouche du nouveau-né doit prendre </span><span><span class=\"nc-yellow_bg\">largement l’aréole</span></span>, <span><span class=\"nc-red nc-bold\">pas seulement le mamelon</span></span></li>\n                <li>Menton et nez contre le sein, tête légèrement inclinée en arrière</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaires</strong></td>\n            <td>\n              <span>Allaitement</span> <strong>souple à la demande</strong> (horaires libres) :\n              <ul>\n                <li>Fréquence moyenne : <span><span class=\"nc-pink nc-bold\">1 tétée toutes les 2 à 3 h</span></span><span class=\"nc-pink nc-bold\"> au début</span>, puis espacement progressif guidé par le nouveau-né</li>\n                <li>Repères pour décider : <span class=\"nc-blue_bg\">regard / comportement de l’enfant</span> (mouvements des yeux, des lèvres, de la tête, main à la bouche)</li>\n                <li><span><span class=\"nc-red_bg\">Ne pas attendre l’agitation ou les pleurs</span></span></li>\n                <li><span><span class=\"nc-red_bg\">Ne pas juger seulement sur la courbe de poids</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée d’une tétée</strong></td>\n            <td>\n              Variable selon l’enfant :\n              <ul>\n                <li>Soit très courte (enfant très actif, tétée efficace sans s’arrêter)</li>\n                <li>Soit plus longue (nouveau-né, prématuré, enfant plus lent ou « tétouille » = succion non nutritive)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’un <span>allaitement</span> efficace</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Repère</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-green nc-bold\">Tétées</span></strong></td><td><span>8–12 <span class=\"nc-green nc-bold\">tétées</span><span class=\"nc-yellow_bg\">/jour</span></span> efficaces, <span class=\"nc-green_bg\">y compris la nuit pendant les 1</span><sup><span class=\"nc-green_bg\">ers</span></sup><span class=\"nc-green_bg\"> mois</span> (succion nutritive)</td></tr>\n          <tr><td><strong>Selles</strong></td><td><span><span class=\"nc-yellow_bg\">&gt; 3 selles</span><span class=\"nc-yellow_bg\">/jour</span></span>, <strong><span class=\"nc-yellow_bg nc-bold\">molles</span>, <span class=\"nc-yellow_bg nc-bold\">grumeleuses</span>, <span class=\"nc-yellow_bg nc-bold\">jaunes</span></strong>, durant les 1<sup>ers</sup> mois</td></tr>\n          <tr><td><strong>Urines</strong></td><td><span><span class=\"nc-yellow_bg\">5–6 couches mouillées et lourdes/jour</span></span> (témoin de diurèse satisfaisante)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils à encourager <em><span>vs</span></em> <span>à éviter</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Encourager ✅</th><th>Éviter ❌</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>Laisser l’enfant avec sa mère <strong><span>24h</span>/24</strong></li>\n                <li><span class=\"nc-blue_bg\">Lavage quotidien des seins à l’eau et au savon</span></li>\n                <li>Protection des mamelons par compresse sèche (éviter la macération)</li>\n                <li>Encourager les associations de soutien à l’AM</li>\n                <li>Boissons abondantes, alimentation variée, riche en protéines et calcium</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Proscription du <strong><span>tabac</span>, <span>alcool</span>, excitants</strong> (café, thé)</li>\n                <li><span>Aucune tétine artificielle ou sucette</span></li>\n                <li><span>Pas de crèmes cosmétiques sur les seins</span> ; <em><span class=\"nc-red nc-bold\">pas besoin d’antisepsie</span></em></li>\n                <li>Aucun médicament ou régime visant à augmenter la sécrétion lactée</li>\n                <li>Production de lait diminue si l’on ajoute des biberons (moins de stimulation par l’enfant)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Couverture des besoins de l’enfant allaité</h4>\n\n      <table>\n        <thead>\n          <tr><th>Période</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant <span>6 mois</span></strong></td>\n            <td>\n              Le LM couvre seul tous les besoins du nourrisson de la naissance à<span> 6 mois</span>, <strong>sauf</strong> :\n              <ul>\n                <li><span>Vitamine D</span> : <span>800–1000 UI/j</span> (<span>400–800 UI</span>/j selon dernier réf de pédiatrie)</li>\n                <li><span>Vitamine K</span> : <span>2 mg PO</span> à la <strong><span class=\"nc-pink_bg nc-bold\">naissance</span></strong>, <span>2 mg PO</span> entre <strong><span class=\"nc-pink_bg nc-bold\">J4–</span><span><span class=\"nc-pink_bg nc-bold\">J7</span></span></strong>, <span>2 mg PO</span> à <strong><span><span class=\"nc-pink_bg nc-bold\">1 mois</span></span></strong> <span class=\"nc-pink_bg\">si AM exclusif</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span>6 mois</span></strong></td>\n            <td>\n              <span class=\"nc-yellow_bg\">Supplémentation en</span> <span><span class=\"nc-yellow_bg nc-bold\">fer</span></span> systématique chez les enfants encore exclusivement ou majoritairement allaités\n              <em>(dès <span>4 mois</span> chez le prématuré et le PAG <span class=\"nc-pink_bg\">si AM exclusif</span>, selon nutrition)</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conservation, transport et réchauffage du LM</h4>\n\n      <table>\n        <thead>\n          <tr><th>Condition</th><th>Durée / modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>T° ambiante (<span>20–25 °C</span>)</strong></td><td><span>4 h</span> maximum</td></tr>\n          <tr><td><strong>Réfrigérateur (<span>≤ 4 °C</span>)</strong></td><td><span><span class=\"nc-pink nc-bold\">48 h</span></span> maximum, T° à vérifier régulièrement</td></tr>\n          <tr>\n            <td><strong>Congélateur (−<span>18 °C</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span>4 mois</span> maximum</li>\n                <li>LM <strong>congelé d’emblée</strong> à son recueil, jamais après conservation au réfrigérateur</li>\n                <li>LM <strong>décongelé</strong> : consommer dans les <span>24 h</span>, <span>jamais recongelé</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Transport</strong></td><td>Glacière ou sac isotherme avec pack de réfrigération</td></tr>\n          <tr>\n            <td><strong>Réchauffage</strong></td>\n            <td>\n              <ul>\n                <li><strong>Comment :</strong> <span class=\"nc-green_bg\">bain-marie</span>, <span class=\"nc-green_bg\">chauffe-biberon</span>, sous <span class=\"nc-green_bg\">robinet d’eau chaude</span></li>\n                <li><span>Pas de micro-ondes</span> (diminue la qualité nutritionnelle + <span class=\"nc-red nc-bold\">risque élevé de brûlure</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Quand consommer ?</strong></td>\n            <td>\n              <ul>\n                <li>Si laissé à T° ambiante : <span>&lt; 1 h</span></li>\n                <li>Si réchauffé : <span>&lt; 30 min</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Inhibition de la lactation <em>(rang C)</em></h4>\n\n      <table>\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              <ul>\n                <li>Femme qui ne souhaite pas allaiter (souvent demandeuse)</li>\n                <li>Raisons médicales : <span><span class=\"nc-red\">fausses couches tardives</span>, <span class=\"nc-red\">IMG</span>, <span class=\"nc-red\">MFIU</span>, décès néonatal</span>, <span class=\"nc-orange_bg\">accouchement </span><strong><span class=\"nc-orange_bg\">sous X</span></strong></li>\n                <li><span>Contre-indication</span> médicale à l’AM : <span>VIH-1, HTLV-1/2, tuberculose active non traitée</span>, <span>chimiothérapie</span> anticancéreuse, traitement radioactif thérapeutique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicamenteuse</strong></td>\n            <td>\n              <span>Pas systématique</span> (effets vasoconstricteurs ; l’arrêt de lactation se fait spontanément en 15 j). Si indiqué, <strong>agonistes dopaminergiques</strong> :\n              <ul>\n                <li><span><span class=\"nc-pink nc-bold\">Lisuride</span></span> : <span>2 cp/j (0,2 mg)</span> pendant 14 j, à débuter dans les <span>24 h</span> post-accouchement, au cours des repas (tolérance digestive)</li>\n                <li><span><span class=\"nc-pink nc-bold\">Cabergoline</span></span> : <span>1 mg</span> en 1 prise unique dans les <span>24 h</span> du post-partum</li>\n                <li><span><span class=\"nc-pink nc-bold\">Quinagolide</span></span></li>\n                <li><span>Bromocriptine n’est plus indiquée</span> (risques <span>CV</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non médicamenteuse</strong></td>\n            <td><em>Pas d’argument scientifique</em> pour : acupuncture, homéopathie, physiothérapie, bandage des seins, brassières, glace…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 32 — Evaluation du nouveau-né · 47 — <span>Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li></ul></details>","frequence":2},{"id":"33-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications de l’allaitement","contenu":"<div class=\"notion-course\"><p>Les complications de l’AM se hiérarchisent en 4 entités : <strong>engorgement pathologique</strong>, <strong>crevasses du <span class=\"nc-blue_bg\">mamelon</span></strong>, <strong><span class=\"nc-yellow_bg\">mastite</span> / <span class=\"nc-orange_bg\">lymphangite</span> / <span class=\"nc-purple_bg\">galactophorite</span></strong>, <strong><span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> du sein</span> lactant</strong>, auxquelles s’ajoute l’<strong>insuffisance de lait</strong>.</p>\n\n      <h4>Engorgement pathologique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"nc-orange_bg\">Stase de lait entraînant une </span><strong><span class=\"nc-orange_bg\">augmentation de la pression intra-alvéolaire</span></strong> → empêche l’écoulement du lait et la tétée de qualité</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              Sein <strong>gonflé, tendu, douloureux, brillant</strong>, avec <span>œdème</span> voire rougeur diffuse :\n              <ul>\n                <li><span><span class=\"nc-blue nc-bold\">Tension douloureuse</span></span> : contemporaine de la montée de lait</li>\n                <li><span>Œdème</span> : stase capillaire et lymphatique</li>\n                <li>Pathologique si : <span><span class=\"nc-red nc-bold\">fièvre</span>, <span class=\"nc-red nc-bold\">douleur</span>, <span class=\"nc-red nc-bold\">gêne à l’écoulement du lait</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td><span>Aucun examen indiqué</span> — diagnostic uniquement clinique</td>\n          </tr>\n          <tr>\n            <td><strong><span>Diagnostic différentiel</span></strong></td>\n            <td><strong>Congestion mammaire</strong> = « montée de lait » (2–3<sup>e</sup> jour du PP, installation physiologique de la lactation)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td><span class=\"nc-green nc-bold\">Tétées</span> <strong>fréquentes et efficaces</strong>, sans limitation de leur nombre ou durée</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"nc-yellow_bg\">Extraction du lait</span></strong> : <span class=\"nc-green nc-bold\">tétées</span> fréquentes et efficaces, <span class=\"nc-green nc-bold\">massage</span>, <span class=\"nc-green nc-bold\">tire-lait</span></li>\n                <li>Reprise des <span class=\"nc-green nc-bold\">tétées</span> efficaces (éviter récidive et <span>évolution</span> vers mastite)</li>\n                <li><span><span class=\"nc-pink nc-bold\">AINS</span></span> ou <span><span class=\"nc-pink nc-bold\">antalgiques</span></span> pour diminuer <span>œdème</span> et <span class=\"nc-red nc-bold\">douleur</span></li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non recommandé</strong></td>\n            <td>Restriction hydrique, bandage des seins (aggravent l’inconfort). Packs de glace ou topiques : efficacité non démontrée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Crevasses du <span class=\"nc-blue_bg\">mamelon</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span><span class=\"nc-yellow_bg\">Rupture</span></span><span class=\"nc-yellow_bg\"> de la barrière cutanée</span> du mamelon</td></tr>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td>\n              Friction anormale mamelon / bouche du bébé = cause principale, favorisée par :\n              <ul>\n                <li><span class=\"nc-red_bg\">Mauvaise prise du sein</span> +++</li>\n                <li>Plus rarement : <strong><span class=\"nc-red nc-bold\">troubles de succion</span></strong> ou <strong><span class=\"nc-red nc-bold\">frein de langue trop court</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong> <em>(4 étapes)</em></td>\n            <td>\n              <ol>\n                <li><span class=\"nc-blue_bg\">Mamelon</span> <strong><span class=\"nc-blue_bg nc-bold\">douloureux</span></strong>, <span class=\"nc-blue_bg\">sans signes cutanés au départ</span> (<span class=\"nc-red nc-bold\">douleur</span> parfois très intense)</li>\n                <li><span class=\"nc-blue_bg\">Mamelon devient</span> <strong><span class=\"nc-blue_bg nc-bold\">rouge</span> et <span class=\"nc-blue_bg nc-bold\">irrité</span></strong></li>\n                <li><span class=\"nc-orange_bg\">Apparition de</span> <strong><span class=\"nc-orange_bg nc-bold\">fissures</span> / <span class=\"nc-orange_bg nc-bold\">érosions</span></strong> cutanées sur l’extrémité du <span class=\"nc-blue_bg\">mamelon</span> (= crevasses)</li>\n                <li><strong>Saignement</strong> possible (non grave, mais inquiétant pour la mère)</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Baisse de la lactation</span></span> : mauvaise stimulation du sein</li>\n                <li><span><span class=\"nc-red nc-bold\">Mastite</span></span> : porte d’entrée infectieuse (<strong><span>staphylocoque</span></strong> ou <strong>candidose</strong>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Positionnement correct au sein + soutien adapté</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Correction de la technique de succion</span> (suffit dans la majorité des cas)</li>\n                <li>Topiques cicatrisants : application de <strong><span class=\"nc-pink nc-bold\">colostrum</span></strong> ou de <strong><span class=\"nc-pink nc-bold\">lait maternel</span></strong> en fin de tétée</li>\n                <li><span>ATB PO</span> si surinfection cutanée (pour éviter la mastite)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"nc-yellow_bg\">Mastite</span> / <span class=\"nc-orange_bg\">Lymphangite</span> / Galactophorite</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définitions</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-yellow_bg\">Mastite</span></strong> : inflammation du sein avec ou sans infection</li>\n                <li><strong><span class=\"nc-orange_bg\">Lymphangite</span></strong> : assimilable à la <span class=\"nc-yellow_bg\">mastite</span> <span>inflammatoire</span></li>\n                <li><strong><span class=\"nc-purple_bg\">Galactophorite</span></strong> : considérée comme une <span class=\"nc-red_bg\">mastite infectieuse</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Cause</strong></td><td><span><span class=\"nc-red nc-bold\">Stase du lait</span></span></td></tr>\n          <tr>\n            <td><strong>Délai</strong></td>\n            <td><span>≤ 3 mois</span> après la <span class=\"nc-pink_bg nc-bold\">naissance</span>, le plus souvent autour de la <strong><span class=\"nc-pink nc-bold\">2</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> semaine du post-partum</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-yellow_bg\">Syndrome grippal brutal</span></span></li>\n                <li><span>Fièvre &gt; 38,5 °C</span> + <span>frissons</span></li>\n                <li><span class=\"nc-red nc-bold\">Douleur</span> dans <strong>1 sein</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <ul>\n                <li>Zone <span>inflammatoire</span> : <strong>rouge, chaude, indurée</strong>, <span class=\"nc-orange_bg\">± </span><span><span class=\"nc-orange_bg\">adénopathie</span></span><span class=\"nc-orange_bg\"> satellite</span></li>\n                <li>Formes sévères : <span><span class=\"nc-red_bg nc-bold\">cellulite</span> <span class=\"nc-red_bg\">avec «</span> <span class=\"nc-red_bg nc-bold\">peau d’orange</span> »</span></li>\n                <li>Clinique ne distingue pas <span class=\"nc-red_bg\">mastite infectieuse</span> <em><span>vs</span></em> non, <strong>mais</strong> : pus dans le lait = <span><span class=\"nc-red nc-bold\">signe de Budin</span></span> → <strong><span class=\"nc-purple nc-bold\">galactophorite</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              Diagnostic clinique, examens <strong>inutiles</strong> en général :\n              <ul>\n                <li><strong><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\"> / </span><span><span class=\"nc-blue_bg\">CRP</span></span></strong> : <span>syndrome inflammatoire</span> avec hyperleucocytose (non spécifique)</li>\n                <li><strong><span class=\"nc-purple_bg\">Prélèvement bactériologique de lait</span></strong> : recommandé</li>\n                <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> mammaire</span></strong> : si atypique, traînant, ou doute sur un <span>abcès</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microbiologie</strong></td>\n            <td>\n              <ul>\n                <li><strong>Prélèvement</strong> après toilette minutieuse du sein, sans prendre les 1<sup>ers</sup> mL extraits</li>\n                <li>Germes : <span><span class=\"nc-yellow_bg\">Staphylocoque doré</span></span> (le plus fréquent), <span><span class=\"nc-purple_bg\">E. coli</span></span>, <span><span class=\"nc-purple_bg\">Streptocoque B</span></span> (à envisager si <strong><span class=\"nc-red nc-bold\">mastite bilatérale</span></strong>)</li>\n                <li><strong>Interprétation</strong> : chez la femme en bonne santé, 10²–10⁵ germes dont <span>70 % de staph à coagulase −</span> ; en faveur d’une <span class=\"nc-red_bg\">mastite infectieuse</span> → <span <span=\"\">&gt;1</span> germe isolé <span>&gt; 10⁶/mL</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span><span class=\"nc-red nc-bold\">Abcès</span></span><span class=\"nc-red nc-bold\"> du sein</span> lactant</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"nc-yellow_bg\">Collection de pus </span><strong><span class=\"nc-yellow_bg\">bien délimitée</span></strong><span class=\"nc-yellow_bg\"> dans le sein</span>, <strong><span class=\"nc-red nc-bold\">complication de la mastite</span></strong></td></tr>\n          <tr><td><strong>Fréquence</strong></td><td><span>≈ 1 %</span> des femmes allaitant</td></tr>\n          <tr><td><strong>Délai</strong></td><td>Vers la <span><span class=\"nc-pink nc-bold\">6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> semaine</span></span> (mais peut survenir à tout moment de la lactation et au <span>sevrage</span>)</td></tr>\n          <tr><td><strong>Début</strong></td><td>Souvent insidieux, douleurs chroniques, tableau à bas bruit</td></tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <ul>\n                <li>Signes inflammatoires sévères : <span class=\"nc-red nc-bold\">douleur</span> <strong>pulsatile / insomniante</strong>, rougeur, chaleur, <span>œdème</span></li>\n                <li><span>Abcès</span> <strong>froid</strong> sans inflammation : plus rare</li>\n                <li><span><span class=\"nc-yellow_bg nc-bold\">Masse</span> <span class=\"nc-yellow_bg nc-bold\">fluctuante</span></span> avec changement de coloration cutanée <span><span class=\"nc-yellow_bg nc-bold\">rouge</span> <span class=\"nc-yellow_bg nc-bold\">violacé</span></span> <em>(fait la différence avec la mastite)</em></li>\n                <li><span><span class=\"nc-red nc-bold\">Nécrose cutanée possible</span></span></li>\n                <li><span><span class=\"nc-red nc-bold\">Fièvre</span></span> <strong>plus modérée</strong> que dans la mastite, <span class=\"nc-brown_bg\">voire absente</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\"> / </span><span><span class=\"nc-blue_bg\">CRP</span></span></strong> : <span>syndrome inflammatoire</span> avec hyperleucocytose, <span>CRP</span> élevée</li>\n                <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span></strong> (radiologue compétent en sénologie) : si doute (spécifique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Éviter toute stase de lait ; agir vite en cas d’engorgement, de canal bouché, de <span class=\"nc-blue_bg\">mamelon</span> <span class=\"nc-blue_bg nc-bold\">douloureux</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Insuffisance de lait (IL)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>IL primaire</strong><br><em>(exceptionnelle)</em></td>\n            <td>\n              Incapacité maternelle à produire du lait en quantité suffisante :\n              <ul>\n                <li>Origine <strong>hormonale</strong></li>\n                <li>Origine <strong><span class=\"nc-red nc-bold\">anatomique</span></strong> : <span><span class=\"nc-pink_bg\">chirurgie</span></span><span class=\"nc-pink_bg\"> esthétique</span> (prothèse mammaire, plastie de <span>réduction</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IL secondaire</strong><br><em>(principalement)</em></td>\n            <td>\n              <ol>\n                <li>Conduite inappropriée de l’AM (<span class=\"nc-yellow_bg\">tétées</span> <span class=\"nc-yellow_bg\">inefficaces</span> et/ou <span class=\"nc-yellow_bg\">trop peu nombreuses</span>)</li>\n                <li>Diminution du transfert de lait + de la sécrétion lactée (favorisée par la <strong><span class=\"nc-red nc-bold\">séparation mère/enfant</span></strong>)</li>\n              </ol>\n            </td>\n          </tr>\n          <tr><td><strong>Conséquence</strong></td><td><span><span class=\"nc-red_bg\">Principale cause d’</span>interruption précoce de l’AM</span></td></tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>\n              <em>Perception inappropriée d’IL = situation la plus fréquente</em>\n              <ul>\n                <li>Conseils / soutien pour restaurer la confiance maternelle</li>\n                <li><span class=\"nc-green_bg\">Mises au sein plus fréquentes pour stimuler la sécrétion lactée</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non efficace ❌</strong></td>\n            <td>Tire-lait, <span>dompéridone</span>, <span>métoclopramide</span>, oxytocine, galactologues à base de plantes : <span>aucune preuve d’efficacité</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pièges chez l’enfant.</strong> L’<span>ictère au <span class=\"nc-pink nc-bold\">lait maternel</span></span> <span class=\"nc-green_bg\">est</span> <strong>sans <span><span>critère de</span> gravité</span></strong> → <span>ne doit pas faire interrompre l’AM</span>. Les <strong>difficultés de succion</strong> (plus fréquentes chez l’immature) peuvent nécessiter l’utilisation temporaire d’un <span class=\"nc-green nc-bold\">tire-lait</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 158 — <span>Sepsis</span> et <span>choc septique</span> · 32 — Evaluation du nouveau-né</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li></ul></details>","frequence":0},{"id":"33-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes et les facteurs favorisant les complications de l’allaitement","contenu":"<div class=\"notion-course\"><h4>Mécanismes des complications</h4>\n\n      <table>\n        <thead>\n          <tr><th>Complication</th><th>Mécanisme principal</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Engorgement pathologique</strong></td>\n            <td>\n              <ul>\n                <li><span>Stase de lait</span> → ↑ pression intra-alvéolaire → blocage de l’écoulement du lait</li>\n                <li>Composante vasculaire associée : stase capillaire et lymphatique → <span>œdème</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Crevasses du <span class=\"nc-blue_bg\">mamelon</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Friction anormale</span> mamelon / bouche du bébé = mécanisme central</li>\n                <li><span>Évolution</span> : <span class=\"nc-red nc-bold\">douleur</span> → rougeur → fissure / <span>érosion</span> → saignement possible</li>\n                <li>Porte d’entrée potentielle pour <strong>S. aureus</strong> ou <strong>candidose</strong> → <span class=\"nc-red nc-bold\">mastite</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Mastite</span> / <span class=\"nc-purple nc-bold\">galactophorite</span></strong></td>\n            <td>\n              <ul>\n                <li>Mécanisme initial = <span><span class=\"nc-red nc-bold\">stase du lait</span></span> (engorgement non drainé)</li>\n                <li>Colonisation <span>bactérienne</span> secondaire : <span><span class=\"nc-yellow_bg\">Staphylocoque</span></span><span class=\"nc-yellow_bg\"> doré</span> (le + fréquent), <span class=\"nc-purple_bg\">E. coli</span>, Strepto B (si <strong>bilatérale</strong>)</li>\n                <li>Pus dans le lait = <strong><span class=\"nc-red nc-bold\">signe de Budin</span></strong> → <span class=\"nc-purple nc-bold\">galactophorite</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Abcès</span></span><span class=\"nc-red nc-bold\"> du sein</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Évolution</span> d’une <span>mastite non ou mal drainée</span> (suspendre l’AM expose à cette complication)</li>\n                <li>Constitution d’une collection purulente bien délimitée</li>\n                <li>Germes : <span><span class=\"nc-purple nc-bold\">staphylocoque</span></span><span class=\"nc-purple nc-bold\"> doré</span>, <span class=\"nc-purple nc-bold\">streptocoque A</span>, <span class=\"nc-purple nc-bold\">entérocoque</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Insuffisance de lait</strong></td>\n            <td>\n              <ul>\n                <li>Primaire (rare) : <span class=\"nc-red nc-bold\">hormonale</span> ou <span class=\"nc-red nc-bold\">anatomique</span> (<span>chirurgie</span> mammaire esthétique / <span>réduction</span>)</li>\n                <li>Secondaire (++) : conduite inappropriée de l’AM, <span class=\"nc-red nc-bold\">séparation mère/enfant</span> → ↓ stimulation neurohormonale → ↓ <span class=\"nc-pink nc-bold\">prolactine</span> / <span class=\"nc-pink nc-bold\">ocytocine</span> → ↓ production</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus — causes d’engorgement <em>(détaillé)</em></h4>\n\n      <table>\n        <thead>\n          <tr><th>Cause</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mauvaise technique d’<span>allaitement</span></strong></td>\n            <td>\n              <ul>\n                <li>Initiation retardée de l’AM à la naissance</li>\n                <li><span class=\"nc-red_bg\">Mauvaise prise du sein</span></li>\n                <li>Conséquences : extraction de lait inefficace, limitation arbitraire fréquence / durée des tétées, compléments, canal lactifère bouché</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-green_bg\">Engorgement physiologique</span></strong></td>\n            <td><span>Incidence</span> <span>−50 %</span> si les tétées se font à la demande de l’enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Obstruction d’un canal lactifère</strong></td>\n            <td>\n              Bouchon de <strong>caséine, lipides, substances solidifiées par sels calciques</strong> :\n              <ul>\n                <li><strong>Clinique</strong> : <span class=\"nc-blue nc-bold\">petit bouton </span><span><span class=\"nc-blue nc-bold\">blanc</span>, voire <span class=\"nc-blue nc-bold\">marron</span> ou <span class=\"nc-blue nc-bold\">verdâtre</span></span> sur le <span class=\"nc-blue_bg\">mamelon</span>, <span class=\"nc-blue_bg nc-bold\">douloureux</span>, engorgement du secteur du canal bouché</li>\n                <li><strong>CAT</strong> : <span class=\"nc-green_bg\">positionner le menton du bébé sur la zone indurée</span> pendant la tétée, éviter tout obstacle à l’écoulement (vêtements serrés), compresses chaudes humides, puis <span class=\"nc-green_bg\">massages doux</span> et retrait du bouchon si insuffisant</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs favorisant les complications</h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Pratique d’AM</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Mise au sein différée</span></li>\n                <li><span class=\"nc-red_bg\">Mauvaise prise du sein</span>, tétées limitées en fréquence ou durée</li>\n                <li>Compléments de lait artificiel en maternité</li>\n                <li><span>Sevrage</span> trop rapide ou trop brutal</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li>Crevasses pré-existantes (porte d’entrée infectieuse)</li>\n                <li>Mauvaise hygiène / défaut de <span class=\"nc-green_bg\">lavage des mains</span></li>\n                <li>Vêtements trop serrés (favorisent l’obstruction canalaire)</li>\n                <li>Antécédent de mastite (récidive si cause non corrigée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bébé</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red nc-bold\">Troubles de succion</span> (<span class=\"nc-red nc-bold\">frein de langue trop court</span> ++)</li>\n                <li>Prématurité, immaturité de la succion</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Anatomique</span></strong></td>\n            <td>\n              <ul>\n                <li>Anomalie d’un canal galactophore</li>\n                <li>Tumeur du sein sous-jacente (à évoquer si mastite récidivante toujours au même endroit)</li>\n                <li><span>Chirurgie</span> mammaire antérieure (prothèse, plastie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span><span class=\"nc-red nc-bold\">Stase du lait</span> + mauvaise technique d’AM = couple causal central</span> des 4 complications mammaires (engorgement → crevasses → <span class=\"nc-red nc-bold\">mastite</span> → <span>abcès</span>). La prévention efficace est <strong>la même</strong> partout : <span>drainage</span> du sein <strong>fréquent, efficace, sans restriction</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 31 — Accouchement - suites de couche normales</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li></ul></details>","frequence":0},{"id":"33-6","rang":"B","rubrique":"Prise en charge","titre":"Allaitement et médicaments, infections et toxiques","contenu":"<div class=\"notion-course\"><ul><li>Vérifier chaque médicament avec une source spécialisée (CRAT/RCP), en tenant compte de la dose, de la voie, de l’âge et de la prématurité de l’enfant. Une mention de prudence ne signifie pas automatiquement arrêt de l’allaitement.</li><li>Éviter alcool et drogues ; accompagner le sevrage tabagique et protéger l’enfant du <span class=\"nc-red_bg\">tabagisme</span> passif. Une difficulté de sevrage ne justifie pas une information culpabilisante ni une décision automatique sans discussion.</li><li>Les infections maternelles ne sont pas toutes des contre-indications : contexte, contagiosité et mesures de prévention propres à l’agent. Mastite habituelle : poursuite de l’allaitement généralement possible, avec traitement adapté.</li><li>VIH : selon HAS 2024, un allaitement peut être envisagé sous conditions strictes de contrôle virologique et de suivi spécialisé maternel–infantile, avec information sur le risque résiduel et la prophylaxie. Ce n’est ni une autorisation générale sans suivi, ni une interdiction universelle.</li><li>Lésion herpétique sur le sein : éviter le contact de l’enfant avec la lésion et le sein atteint jusqu’à guérison selon avis spécialisé ; le sein sain peut être utilisé avec précautions.</li><li>Prématurité, traitement cytotoxique ou situation infectieuse particulière : avis spécialisé et soutien d’une solution nutritionnelle sûre.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li></ul></details>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">Fièvre &gt; 38,5 °C</span> + <span class=\"kw-clinique\">syndrome grippal brutal</span> + douleur dans un sein → <span class=\"kw-def\">mastite</span></li><li><span class=\"kw-alerte\">Masse fluctuante</span> avec peau <span class=\"kw-clinique\">rouge violacée</span> → <span class=\"kw-def\">abcès du sein lactant</span> (complication de la mastite)</li><li><span class=\"kw-clinique\">Signe de Budin</span> (pus dans le lait) → <span class=\"kw-def\">galactophorite</span> (mastite infectieuse)</li><li><span class=\"kw-alerte\">Mastite récidivante toujours au même endroit</span> → éliminer une <span class=\"kw-etio\">tumeur du sein</span></li></ul>","principes":"<p>Chaque complication a sa propre ligne de conduite — du plus simple (correction de technique) au plus invasif (<span class=\"kw-ttt\">drainage</span> chirurgical). Le <strong>drainage du sein</strong> est le fil conducteur commun : <span class=\"kw-ci\">suspendre l'allaitement expose au développement d'un abcès</span>.</p><p><strong>Engorgement pathologique</strong></p><p><span class=\"kw-ci\">Restriction hydrique et bandage des seins déconseillés</span> (aggravent l'inconfort)</p><ul><li>Extraction du lait : <span class=\"kw-ttt\">tétées fréquentes et efficaces</span> ou <span class=\"kw-ttt\">tire-lait</span> ou <span class=\"kw-ttt\">massage</span></li><li><span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">antalgiques</span> pour réduire l'<span class=\"kw-clinique\">œdème</span> et la douleur</li></ul><p><strong>Crevasses des mamelons</strong></p><p>Meilleure prévention = <span class=\"kw-ttt\">positionnement correct au sein</span> dès le départ</p><ul><li>Correction de la <span class=\"kw-clinique\">technique de succion</span> : suffit dans la majorité des cas</li><li>Topiques cicatrisants : <span class=\"kw-ttt\">colostrum</span> ou <span class=\"kw-ttt\">lait maternel</span> appliqué sur le mamelon en fin de tétée</li><li><span class=\"kw-ttt\">ATB per os</span> si <span class=\"kw-etio\">surinfection cutanée</span> (pour prévenir la mastite)</li></ul><p><strong>Mastite <span class=\"q\">— lymphangite / galactophorite</span></strong></p><p><span class=\"kw-ci\">Suspension de l'allaitement expose à l'abcès</span> — poursuivre le <span class=\"kw-ttt\">drainage</span> même si le lait contient du pus (tire-lait + jeter le lait jusqu'à guérison)</p><ul><li><span class=\"kw-ttt\">Drainage du sein</span> efficace en priorité (tétées sans restriction, extraction manuelle ou tire-lait)</li><li><span class=\"kw-ttt\">Pénicilline M</span> (<span class=\"kw-chiffre\">5–7 jours</span>) si mastite infectieuse confirmée, symptômes graves d'emblée ou n'améliorant pas en <span class=\"kw-chiffre\">12–24h</span>, ou <span class=\"kw-clinique\">lésion</span> du mamelon visible</li><li><span class=\"kw-ttt\">Paracétamol</span> ± <span class=\"kw-ttt\">AINS</span> à visée <span class=\"kw-ttt\">antalgique</span></li></ul><p><strong><span class=\"kw-clinique\">Abcès</span> du sein lactant</strong></p><p>Prélèvements bactériologiques pour identification et <span class=\"kw-bio\">antibiogramme</span> (germes fréquents : <span class=\"kw-etio\">staphylocoque doré</span>, <span class=\"kw-etio\">streptocoque A</span>, <span class=\"kw-etio\">entérocoque</span>)</p><ul><li>Formes simples (<span class=\"kw-chiffre\">&lt; 3 cm</span>, homogènes) : <span class=\"kw-ttt\">ponctions itératives à l'aiguille</span> (alternative au <span class=\"kw-ttt\">drainage</span> chirurgical)</li><li>Formes non simples : <span class=\"kw-ttt\">incision et drainage chirurgical sous AG</span></li><li><span class=\"kw-ttt\">Drainage par tire-lait</span> du sein affecté — <span class=\"kw-ci\">allaitement</span> poursuivi du sein controlatéral</li></ul>","suivi":"<p><strong>Mastite :</strong> <span class=\"kw-def\">surveillance</span> rigoureuse pour dépister une <span class=\"kw-alerte\">évolution en abcès</span> (absence d'amélioration sous traitement = indication d'<span class=\"kw-imagerie\">échographie mammaire</span>).<br><strong>Mastite récurrente :</strong> rechercher mastite mal traitée initialement, persistance d'une mauvaise technique d'<span class=\"kw-ci\">allaitement</span>, infection cutanée associée, ou <span class=\"kw-alerte\">cause entraînant un faible drainage</span> (anomalie d'un canal, <span class=\"kw-etio\">tumeur</span>).<br><strong><span class=\"kw-clinique\">Abcès</span> :</strong> <span class=\"kw-imagerie\">échographie mammaire</span> par radiologue compétent en sénologie si doute diagnostique.</p>"},"cards":[{"i":"3bc640a4d264","n":33,"o":"33-1","u":"Prise en charge","t":"Connaître les bénéfices de l’allaitement maternel","q":"Que retenir concernant les bénéfices de l’allaitement maternel ?","a":"<div class=\"notion-course\"><p>Le <span><span class=\"nc-pink nc-bold\">lait maternel</span> (LM)</span> est le <strong>lait le plus adapté</strong> à la croissance et au développement du nourrisson. Sa composition est <strong>variable</strong> (selon le <span>stade</span> de lactation, le terme, l’âge, le nycthémère, voire le moment de la tétée), constamment ajustée aux besoins physiologiques. Il a <strong><span <span=\"\">&gt;2</span> grandes fonctions</strong> chez l’enfant : <span>nutritive</span> et <span>immunologique</span>.</p>\n\n      <h4>Composition du <span class=\"nc-pink nc-bold\">lait maternel</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Éléments</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Éléments nutritifs</strong></td>\n            <td>\n              <ul>\n                <li>Eau, oligoéléments</li>\n                <li><span><span class=\"nc-pink_bg\">Lactose</span></span>, <span class=\"nc-pink_bg\">protéines solubles</span> (α-lactoglobulines)</li>\n                <li><span>AGE</span> (acide linoléique, α-linolénique), <span><span class=\"nc-pink_bg\">triglycérides</span></span><span class=\"nc-pink_bg\"> à chaîne longue</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Éléments non nutritifs</strong><br><em>(rôle immunologique = immunité passive)</em></td>\n            <td>\n              <ul>\n                <li>Protéines essentielles : <span><span class=\"nc-blue_bg\">lysozyme</span></span>, <span><span class=\"nc-blue_bg\">immunoglobulines</span></span>, <span><span class=\"nc-blue_bg\">lactoferrine</span></span></li>\n                <li>Éléments cellulaires : <span><span class=\"nc-blue_bg\">lymphocytes</span></span>, <span><span class=\"nc-blue_bg\">polynucléaires</span></span>, <span class=\"nc-blue_bg\">macrophages</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Teneur basse</strong> <em>(à supplémenter)</em></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Caséine</span></span> (protéine à digestion lente)</li>\n                <li><span>Vitamine D</span>, <span>Vitamine K</span>, <span>Fer</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Alimentation maternelle</strong></td>\n            <td>Peu d’impact sur la composition du LM, <em>sauf</em> teneur en : graisses (AG polyinsaturés), iode, sélénium, vitamines A et B</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Variations dans les 1ers jours d’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th><span>Stade</span></th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-green nc-bold\">Colostrum</span></strong><br><em>(1ers allaitements)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Couleur </span><strong><span class=\"nc-yellow_bg\">orangée</span></strong></li>\n                <li><span><span class=\"nc-red nc-bold\">Pauvre en graisses</span></span></li>\n                <li><span class=\"nc-green_bg\">Riche en </span><span><span class=\"nc-green_bg\">IgA</span></span>, <span class=\"nc-green_bg\">glycoprotéines</span>, <span class=\"nc-green_bg\">oligosaccharides</span>, <span class=\"nc-green_bg\">cellules</span> <span class=\"nc-green_bg\">immunitaires</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span>J15</span></strong></td>\n            <td><span class=\"nc-green_bg\">Lait de plus en plus </span><strong><span class=\"nc-green_bg\">riche en</span> <span class=\"nc-green_bg nc-bold\">graisses</span></strong> <em>(rôle dans la maturation cérébrale et rétinienne)</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Comparaison <span class=\"nc-pink nc-bold\">lait maternel</span> <em><span>vs</span></em> lait de vache</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Particularité du LM</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Protéines</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-red_bg\">Plus pauvre en caséines</span></strong> (explique sa couleur translucide)</li>\n                <li><span class=\"nc-green_bg\">Plus riche en protéines non nutritives</span> (<span class=\"nc-green_bg\">lactoferrine</span>, Ig, <span class=\"nc-blue_bg\">lysozyme</span>) → mieux adapté à un nouveau-né au système immunitaire immature</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td><span class=\"nc-red_bg\">Moins riche en </span><span><span class=\"nc-red_bg\">vitamine D</span></span> → source de <span><span class=\"nc-orange nc-bold\">rachitisme</span></span> (intérêt d’une <strong>supplémentation systématique</strong>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bénéfices chez la mère</h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Bénéfice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cancer</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Diminution du cancer de l’</span><span><span class=\"nc-red_bg nc-bold\">ovaire</span></span> : <span>−8 %</span> du risque épithélial dès <span>5 mois</span> d’AM</li>\n                <li><span class=\"nc-red_bg\">Diminution du cancer du</span> <span><span class=\"nc-red_bg nc-bold\">sein</span></span> : <span>−4 %</span>/an d’AM, encore plus marqué si <strong>BRCA1</strong> (<span>−40 %</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vasculaire</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-green_bg\">Perte de poids</span></span><span class=\"nc-green_bg\"> / diminution de la </span><span><span class=\"nc-green_bg\">masse</span></span><span class=\"nc-green_bg\"> grasse plus rapides en post-partum</span></li>\n                <li>Diminution de : <strong><span><span class=\"nc-orange nc-bold\">obésité</span></span></strong>, <strong><span><span class=\"nc-orange nc-bold\">DT2</span></span></strong>, <strong><span class=\"nc-orange nc-bold\">dyslipidémies</span></strong>, <strong><span><span class=\"nc-orange nc-bold\">HTA</span></span></strong>, <strong><span class=\"nc-orange nc-bold\">maladie</span> <span>CV</span></strong> <em>(bénéfice persistant après ménopause)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychique</strong></td>\n            <td>\n              <ul>\n                <li>Diminution de la fréquence de la <span><span class=\"nc-orange nc-bold\">dépression du post-partum</span></span></li>\n                <li><span class=\"nc-green_bg\">Diminue la réponse au stress</span>, améliore le bien-être et l’estime de soi</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              <ul>\n                <li>Favorise le <strong>lien mère/enfant</strong></li>\n                <li>Avantage financier (meilleure protection contre la dénutrition dans les pays en voie de développement)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bénéfices chez l’enfant</h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Bénéfice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Principal +++</strong></td>\n            <td><span>Diminution des infections pédiatriques</span> : <strong>ORL</strong>, <strong>gastroentérite</strong>, <strong>respiratoire</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pathologies réduites</strong></td>\n            <td>\n              <ul>\n                <li>Allergies : <strong><span><span class=\"nc-orange nc-bold\">eczéma</span></span></strong> chez le &lt;<span> 2 ans</span>, <strong><span class=\"nc-orange nc-bold\">rhinite </span><span><span class=\"nc-orange nc-bold\">allergique</span></span></strong> chez le &lt;<span> 5 ans</span>, <strong><span><span class=\"nc-orange nc-bold\">asthme</span></span></strong> entre <span>5–18 ans</span></li>\n                <li>Leucémies pédiatriques : <span>−20 %</span> dès <span>6 mois</span> d’AM</li>\n                <li>Risque de <strong><span class=\"nc-orange nc-bold\">malocclusion dentaire</span></strong></li>\n                <li>Probable <span>réduction</span> du risque d’<strong><span><span class=\"nc-orange nc-bold\">obésité</span></span></strong> et de <strong><span><span class=\"nc-orange nc-bold\">diabète</span></span></strong></li>\n                <li><span><span class=\"nc-red_bg nc-bold\">Mort subite du nourrisson</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Intelligence</strong></td>\n            <td>Gain de QI <span>+3</span></td>\n          </tr>\n          <tr>\n            <td><strong>Spécifique du prématuré</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Améliore la tolérance digestive et le développement cognitif</span></li>\n                <li><span class=\"nc-red_bg\">Réduit le risque d’</span><span><span class=\"nc-red_bg nc-bold\">ECUN</span></span> (entérocolite ulcéro-nécrosante)</li>\n                <li>Modalités possibles : sein, tasse, pipette, cuillère, SNG, ou <strong>lait de <span class=\"nc-pink nc-bold\">Lactarium</span></strong> <em>(centre de collecte de lait de donneuses bénévoles pour prématurés et nv-né de faible poids de <span class=\"nc-pink_bg nc-bold\">naissance</span>)</em></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> Les <strong>modifications de l’aspect esthétique des seins</strong> sont plus liées <strong>à la <span>grossesse</span> elle-même</strong> qu’à l’<span>allaitement</span>. C’est un argument fréquemment opposé à l’AM qu’il faut savoir corriger.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 47 — <span>Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 69 — Trouble psy <span>grossesse</span> - postpartum</em></p></div>"},{"i":"7812b90d4f05","n":33,"o":"33-2","u":"Epidémiologie","t":"Connaître la prévalence, les facteurs influençant l’allaitement","q":"Que retenir concernant la prévalence, les facteurs influençant l’allaitement ?","a":"<div class=\"notion-course\"><h4><span>Épidémiologie</span> — chiffres clés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Donnée</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Géographie</strong></td>\n            <td>\n              <ul>\n                <li><span>Prévalence</span> et durée de l’AM en France sont <strong>parmi les plus faibles d’Europe</strong></li>\n                <li>Régions où la <span>prévalence</span> <span class=\"nc-green_bg\">est</span> plus élevée : <span class=\"nc-green_bg\">Île-de-France</span>, <span class=\"nc-green_bg\">Est</span>, <span class=\"nc-green_bg\">départements d’outre-mer</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Prévalence</span></strong></td>\n            <td>\n              <ul>\n                <li>En maternité : <span>70 %</span> (<span>60 %</span> exclusif,<span> 10 %</span> partiel)</li>\n                <li>À <span>3 mois</span> : <span>40 %</span></li>\n                <li>À <span>6 mois</span> : <span>&lt; 20 %</span> <em>(ancien réf :<span> 10 %</span> à<span> 1 an</span>)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>\n              <ul>\n                <li>Durée médiane (ancien réf) : <span>15 semaines</span> (dont 24 j exclusifs)</li>\n                <li>Durée idéale recommandée : <span><span class=\"nc-green nc-bold\">4 à 6 mois</span></span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs favorisant l’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Terrain</span></strong></td>\n            <td>\n              <ul>\n                <li>Femme âgée, diplômée, <span class=\"nc-blue_bg\">profession qualifiée</span>, <strong>primipare</strong></li>\n                <li><strong>Soutien</strong> de l’entourage, prise de décision d’AM <strong>avant la <span>grossesse</span></strong></li>\n                <li>Accouchement dans une maternité labellisée <span>IHAB</span> (Initiative Hôpital Ami des Bébés)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Promotion</strong></td>\n            <td>\n              <ul>\n                <li>Promotion de l’AM = objectif du <strong>Programme National Nutrition Santé (PNNS)</strong></li>\n                <li><strong>Code du travail</strong> : pauses sur le temps de travail, lieux appropriés pour exprimer le lait, horaires souples</li>\n                <li>Implication des <strong>pédiatres</strong> doit être exemplaire</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Facteurs de risque</span> d’arrêt prématuré <span>(5 catégories)</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li>Jeune, primipare, célibataire, faible statut socio-économique, mère récemment immigrée</li>\n                <li>Décision tardive d’allaiter, 1<sup>ère</sup> expérience d’<span>allaitement</span>, expérience passée négative</li>\n                <li><span><span class=\"nc-red nc-bold\">Utilisation précoce d’une tétine</span></span>, <span><span class=\"nc-red_bg\">tabagisme</span></span>, <span><span class=\"nc-red_bg\">obésité</span></span>, <span class=\"nc-red_bg\">exercice d’une profession</span></li>\n                <li><span class=\"nc-red_bg\">Manque de confiance</span>, incertitude sur la quantité de lait prise, <span class=\"nc-red_bg\">perception d’une insuffisance de lait</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bébé</strong></td>\n            <td>\n              <ul>\n                <li><span>Perte de poids</span> <span>&gt; 10 %</span></li>\n                <li><span class=\"nc-red_bg\">Faible prise de poids</span></li>\n                <li><span class=\"nc-red_bg\">Problèmes de succion</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Entourage</strong></td>\n            <td>\n              <ul>\n                <li>Absence de soutien du partenaire</li>\n                <li>Perception négative du père</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Organisation en maternité</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Mise au sein différée</span>, 1<sup>er</sup> peau à peau retardé</li>\n                <li>Méconnaissance et manque de soutien des professionnels</li>\n                <li><span>Allaitement</span> à horaires fixes</li>\n                <li><span><span class=\"nc-red nc-bold\">Recours aux compléments de lait artificiel en maternité</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Politiques</strong></td>\n            <td>Congé de maternité court et peu rémunéré</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 47 — <span>Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p></div>"},{"i":"b25af11fada9","n":33,"o":"33-3","u":"Prise en charge","t":"Savoir expliquer les modalité pratiques de l’allaitement maternel","q":"Que retenir concernant expliquer les modalité pratiques de l’allaitement maternel ?","a":"<div class=\"notion-course\"><h4>Conseils pour l’<span>allaitement</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Conseil</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>ère</sup> tétée</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Mise au sein </span><strong><span class=\"nc-green_bg\">immédiate</span></strong>, <span class=\"nc-green_bg\">si possible en salle de travail</span></li>\n                <li>Délai : sans précipitation, mais <span><span class=\"nc-pink nc-bold\">&lt; 30 min</span></span> après la naissance</li>\n                <li>Colostrum riche en Ig → favorise la <strong>montée laiteuse</strong> ; réflexe de succion à son maximum</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Mère assise ou couchée</span></li>\n                <li><span class=\"nc-blue_bg\">Donner les 2 seins à chaque tétée</span> <em>(alterner → diminue les complications)</em></li>\n                <li><span class=\"nc-yellow_bg\">Bouche du nouveau-né doit prendre </span><span><span class=\"nc-yellow_bg\">largement l’aréole</span></span>, <span><span class=\"nc-red nc-bold\">pas seulement le mamelon</span></span></li>\n                <li>Menton et nez contre le sein, tête légèrement inclinée en arrière</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaires</strong></td>\n            <td>\n              <span>Allaitement</span> <strong>souple à la demande</strong> (horaires libres) :\n              <ul>\n                <li>Fréquence moyenne : <span><span class=\"nc-pink nc-bold\">1 tétée toutes les 2 à 3 h</span></span><span class=\"nc-pink nc-bold\"> au début</span>, puis espacement progressif guidé par le nouveau-né</li>\n                <li>Repères pour décider : <span class=\"nc-blue_bg\">regard / comportement de l’enfant</span> (mouvements des yeux, des lèvres, de la tête, main à la bouche)</li>\n                <li><span><span class=\"nc-red_bg\">Ne pas attendre l’agitation ou les pleurs</span></span></li>\n                <li><span><span class=\"nc-red_bg\">Ne pas juger seulement sur la courbe de poids</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée d’une tétée</strong></td>\n            <td>\n              Variable selon l’enfant :\n              <ul>\n                <li>Soit très courte (enfant très actif, tétée efficace sans s’arrêter)</li>\n                <li>Soit plus longue (nouveau-né, prématuré, enfant plus lent ou « tétouille » = succion non nutritive)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’un <span>allaitement</span> efficace</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Repère</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-green nc-bold\">Tétées</span></strong></td><td><span>8–12 <span class=\"nc-green nc-bold\">tétées</span><span class=\"nc-yellow_bg\">/jour</span></span> efficaces, <span class=\"nc-green_bg\">y compris la nuit pendant les 1</span><sup><span class=\"nc-green_bg\">ers</span></sup><span class=\"nc-green_bg\"> mois</span> (succion nutritive)</td></tr>\n          <tr><td><strong>Selles</strong></td><td><span><span class=\"nc-yellow_bg\">&gt; 3 selles</span><span class=\"nc-yellow_bg\">/jour</span></span>, <strong><span class=\"nc-yellow_bg nc-bold\">molles</span>, <span class=\"nc-yellow_bg nc-bold\">grumeleuses</span>, <span class=\"nc-yellow_bg nc-bold\">jaunes</span></strong>, durant les 1<sup>ers</sup> mois</td></tr>\n          <tr><td><strong>Urines</strong></td><td><span><span class=\"nc-yellow_bg\">5–6 couches mouillées et lourdes/jour</span></span> (témoin de diurèse satisfaisante)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils à encourager <em><span>vs</span></em> <span>à éviter</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Encourager ✅</th><th>Éviter ❌</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>Laisser l’enfant avec sa mère <strong><span>24h</span>/24</strong></li>\n                <li><span class=\"nc-blue_bg\">Lavage quotidien des seins à l’eau et au savon</span></li>\n                <li>Protection des mamelons par compresse sèche (éviter la macération)</li>\n                <li>Encourager les associations de soutien à l’AM</li>\n                <li>Boissons abondantes, alimentation variée, riche en protéines et calcium</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Proscription du <strong><span>tabac</span>, <span>alcool</span>, excitants</strong> (café, thé)</li>\n                <li><span>Aucune tétine artificielle ou sucette</span></li>\n                <li><span>Pas de crèmes cosmétiques sur les seins</span> ; <em><span class=\"nc-red nc-bold\">pas besoin d’antisepsie</span></em></li>\n                <li>Aucun médicament ou régime visant à augmenter la sécrétion lactée</li>\n                <li>Production de lait diminue si l’on ajoute des biberons (moins de stimulation par l’enfant)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Couverture des besoins de l’enfant allaité</h4>\n\n      <table>\n        <thead>\n          <tr><th>Période</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant <span>6 mois</span></strong></td>\n            <td>\n              Le LM couvre seul tous les besoins du nourrisson de la naissance à<span> 6 mois</span>, <strong>sauf</strong> :\n              <ul>\n                <li><span>Vitamine D</span> : <span>800–1000 UI/j</span> (<span>400–800 UI</span>/j selon dernier réf de pédiatrie)</li>\n                <li><span>Vitamine K</span> : <span>2 mg PO</span> à la <strong><span class=\"nc-pink_bg nc-bold\">naissance</span></strong>, <span>2 mg PO</span> entre <strong><span class=\"nc-pink_bg nc-bold\">J4–</span><span><span class=\"nc-pink_bg nc-bold\">J7</span></span></strong>, <span>2 mg PO</span> à <strong><span><span class=\"nc-pink_bg nc-bold\">1 mois</span></span></strong> <span class=\"nc-pink_bg\">si AM exclusif</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span>6 mois</span></strong></td>\n            <td>\n              <span class=\"nc-yellow_bg\">Supplémentation en</span> <span><span class=\"nc-yellow_bg nc-bold\">fer</span></span> systématique chez les enfants encore exclusivement ou majoritairement allaités\n              <em>(dès <span>4 mois</span> chez le prématuré et le PAG <span class=\"nc-pink_bg\">si AM exclusif</span>, selon nutrition)</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conservation, transport et réchauffage du LM</h4>\n\n      <table>\n        <thead>\n          <tr><th>Condition</th><th>Durée / modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>T° ambiante (<span>20–25 °C</span>)</strong></td><td><span>4 h</span> maximum</td></tr>\n          <tr><td><strong>Réfrigérateur (<span>≤ 4 °C</span>)</strong></td><td><span><span class=\"nc-pink nc-bold\">48 h</span></span> maximum, T° à vérifier régulièrement</td></tr>\n          <tr>\n            <td><strong>Congélateur (−<span>18 °C</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span>4 mois</span> maximum</li>\n                <li>LM <strong>congelé d’emblée</strong> à son recueil, jamais après conservation au réfrigérateur</li>\n                <li>LM <strong>décongelé</strong> : consommer dans les <span>24 h</span>, <span>jamais recongelé</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Transport</strong></td><td>Glacière ou sac isotherme avec pack de réfrigération</td></tr>\n          <tr>\n            <td><strong>Réchauffage</strong></td>\n            <td>\n              <ul>\n                <li><strong>Comment :</strong> <span class=\"nc-green_bg\">bain-marie</span>, <span class=\"nc-green_bg\">chauffe-biberon</span>, sous <span class=\"nc-green_bg\">robinet d’eau chaude</span></li>\n                <li><span>Pas de micro-ondes</span> (diminue la qualité nutritionnelle + <span class=\"nc-red nc-bold\">risque élevé de brûlure</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Quand consommer ?</strong></td>\n            <td>\n              <ul>\n                <li>Si laissé à T° ambiante : <span>&lt; 1 h</span></li>\n                <li>Si réchauffé : <span>&lt; 30 min</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Inhibition de la lactation <em>(rang C)</em></h4>\n\n      <table>\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              <ul>\n                <li>Femme qui ne souhaite pas allaiter (souvent demandeuse)</li>\n                <li>Raisons médicales : <span><span class=\"nc-red\">fausses couches tardives</span>, <span class=\"nc-red\">IMG</span>, <span class=\"nc-red\">MFIU</span>, décès néonatal</span>, <span class=\"nc-orange_bg\">accouchement </span><strong><span class=\"nc-orange_bg\">sous X</span></strong></li>\n                <li><span>Contre-indication</span> médicale à l’AM : <span>VIH-1, HTLV-1/2, tuberculose active non traitée</span>, <span>chimiothérapie</span> anticancéreuse, traitement radioactif thérapeutique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicamenteuse</strong></td>\n            <td>\n              <span>Pas systématique</span> (effets vasoconstricteurs ; l’arrêt de lactation se fait spontanément en 15 j). Si indiqué, <strong>agonistes dopaminergiques</strong> :\n              <ul>\n                <li><span><span class=\"nc-pink nc-bold\">Lisuride</span></span> : <span>2 cp/j (0,2 mg)</span> pendant 14 j, à débuter dans les <span>24 h</span> post-accouchement, au cours des repas (tolérance digestive)</li>\n                <li><span><span class=\"nc-pink nc-bold\">Cabergoline</span></span> : <span>1 mg</span> en 1 prise unique dans les <span>24 h</span> du post-partum</li>\n                <li><span><span class=\"nc-pink nc-bold\">Quinagolide</span></span></li>\n                <li><span>Bromocriptine n’est plus indiquée</span> (risques <span>CV</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non médicamenteuse</strong></td>\n            <td><em>Pas d’argument scientifique</em> pour : acupuncture, homéopathie, physiothérapie, bandage des seins, brassières, glace…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 32 — Evaluation du nouveau-né · 47 — <span>Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p></div>"},{"i":"2b327fd109f6","n":33,"o":"33-4","u":"Diagnostic positif","t":"Connaître les complications de l’allaitement","q":"Que retenir concernant les complications de l’allaitement ?","a":"<div class=\"notion-course\"><p>Les complications de l’AM se hiérarchisent en 4 entités : <strong>engorgement pathologique</strong>, <strong>crevasses du <span class=\"nc-blue_bg\">mamelon</span></strong>, <strong><span class=\"nc-yellow_bg\">mastite</span> / <span class=\"nc-orange_bg\">lymphangite</span> / <span class=\"nc-purple_bg\">galactophorite</span></strong>, <strong><span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> du sein</span> lactant</strong>, auxquelles s’ajoute l’<strong>insuffisance de lait</strong>.</p>\n\n      <h4>Engorgement pathologique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"nc-orange_bg\">Stase de lait entraînant une </span><strong><span class=\"nc-orange_bg\">augmentation de la pression intra-alvéolaire</span></strong> → empêche l’écoulement du lait et la tétée de qualité</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              Sein <strong>gonflé, tendu, douloureux, brillant</strong>, avec <span>œdème</span> voire rougeur diffuse :\n              <ul>\n                <li><span><span class=\"nc-blue nc-bold\">Tension douloureuse</span></span> : contemporaine de la montée de lait</li>\n                <li><span>Œdème</span> : stase capillaire et lymphatique</li>\n                <li>Pathologique si : <span><span class=\"nc-red nc-bold\">fièvre</span>, <span class=\"nc-red nc-bold\">douleur</span>, <span class=\"nc-red nc-bold\">gêne à l’écoulement du lait</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td><span>Aucun examen indiqué</span> — diagnostic uniquement clinique</td>\n          </tr>\n          <tr>\n            <td><strong><span>Diagnostic différentiel</span></strong></td>\n            <td><strong>Congestion mammaire</strong> = « montée de lait » (2–3<sup>e</sup> jour du PP, installation physiologique de la lactation)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td><span class=\"nc-green nc-bold\">Tétées</span> <strong>fréquentes et efficaces</strong>, sans limitation de leur nombre ou durée</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"nc-yellow_bg\">Extraction du lait</span></strong> : <span class=\"nc-green nc-bold\">tétées</span> fréquentes et efficaces, <span class=\"nc-green nc-bold\">massage</span>, <span class=\"nc-green nc-bold\">tire-lait</span></li>\n                <li>Reprise des <span class=\"nc-green nc-bold\">tétées</span> efficaces (éviter récidive et <span>évolution</span> vers mastite)</li>\n                <li><span><span class=\"nc-pink nc-bold\">AINS</span></span> ou <span><span class=\"nc-pink nc-bold\">antalgiques</span></span> pour diminuer <span>œdème</span> et <span class=\"nc-red nc-bold\">douleur</span></li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non recommandé</strong></td>\n            <td>Restriction hydrique, bandage des seins (aggravent l’inconfort). Packs de glace ou topiques : efficacité non démontrée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Crevasses du <span class=\"nc-blue_bg\">mamelon</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span><span class=\"nc-yellow_bg\">Rupture</span></span><span class=\"nc-yellow_bg\"> de la barrière cutanée</span> du mamelon</td></tr>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td>\n              Friction anormale mamelon / bouche du bébé = cause principale, favorisée par :\n              <ul>\n                <li><span class=\"nc-red_bg\">Mauvaise prise du sein</span> +++</li>\n                <li>Plus rarement : <strong><span class=\"nc-red nc-bold\">troubles de succion</span></strong> ou <strong><span class=\"nc-red nc-bold\">frein de langue trop court</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong> <em>(4 étapes)</em></td>\n            <td>\n              <ol>\n                <li><span class=\"nc-blue_bg\">Mamelon</span> <strong><span class=\"nc-blue_bg nc-bold\">douloureux</span></strong>, <span class=\"nc-blue_bg\">sans signes cutanés au départ</span> (<span class=\"nc-red nc-bold\">douleur</span> parfois très intense)</li>\n                <li><span class=\"nc-blue_bg\">Mamelon devient</span> <strong><span class=\"nc-blue_bg nc-bold\">rouge</span> et <span class=\"nc-blue_bg nc-bold\">irrité</span></strong></li>\n                <li><span class=\"nc-orange_bg\">Apparition de</span> <strong><span class=\"nc-orange_bg nc-bold\">fissures</span> / <span class=\"nc-orange_bg nc-bold\">érosions</span></strong> cutanées sur l’extrémité du <span class=\"nc-blue_bg\">mamelon</span> (= crevasses)</li>\n                <li><strong>Saignement</strong> possible (non grave, mais inquiétant pour la mère)</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-red nc-bold\">Baisse de la lactation</span></span> : mauvaise stimulation du sein</li>\n                <li><span><span class=\"nc-red nc-bold\">Mastite</span></span> : porte d’entrée infectieuse (<strong><span>staphylocoque</span></strong> ou <strong>candidose</strong>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Positionnement correct au sein + soutien adapté</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Correction de la technique de succion</span> (suffit dans la majorité des cas)</li>\n                <li>Topiques cicatrisants : application de <strong><span class=\"nc-pink nc-bold\">colostrum</span></strong> ou de <strong><span class=\"nc-pink nc-bold\">lait maternel</span></strong> en fin de tétée</li>\n                <li><span>ATB PO</span> si surinfection cutanée (pour éviter la mastite)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"nc-yellow_bg\">Mastite</span> / <span class=\"nc-orange_bg\">Lymphangite</span> / Galactophorite</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définitions</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-yellow_bg\">Mastite</span></strong> : inflammation du sein avec ou sans infection</li>\n                <li><strong><span class=\"nc-orange_bg\">Lymphangite</span></strong> : assimilable à la <span class=\"nc-yellow_bg\">mastite</span> <span>inflammatoire</span></li>\n                <li><strong><span class=\"nc-purple_bg\">Galactophorite</span></strong> : considérée comme une <span class=\"nc-red_bg\">mastite infectieuse</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Cause</strong></td><td><span><span class=\"nc-red nc-bold\">Stase du lait</span></span></td></tr>\n          <tr>\n            <td><strong>Délai</strong></td>\n            <td><span>≤ 3 mois</span> après la <span class=\"nc-pink_bg nc-bold\">naissance</span>, le plus souvent autour de la <strong><span class=\"nc-pink nc-bold\">2</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> semaine du post-partum</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-yellow_bg\">Syndrome grippal brutal</span></span></li>\n                <li><span>Fièvre &gt; 38,5 °C</span> + <span>frissons</span></li>\n                <li><span class=\"nc-red nc-bold\">Douleur</span> dans <strong>1 sein</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <ul>\n                <li>Zone <span>inflammatoire</span> : <strong>rouge, chaude, indurée</strong>, <span class=\"nc-orange_bg\">± </span><span><span class=\"nc-orange_bg\">adénopathie</span></span><span class=\"nc-orange_bg\"> satellite</span></li>\n                <li>Formes sévères : <span><span class=\"nc-red_bg nc-bold\">cellulite</span> <span class=\"nc-red_bg\">avec «</span> <span class=\"nc-red_bg nc-bold\">peau d’orange</span> »</span></li>\n                <li>Clinique ne distingue pas <span class=\"nc-red_bg\">mastite infectieuse</span> <em><span>vs</span></em> non, <strong>mais</strong> : pus dans le lait = <span><span class=\"nc-red nc-bold\">signe de Budin</span></span> → <strong><span class=\"nc-purple nc-bold\">galactophorite</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              Diagnostic clinique, examens <strong>inutiles</strong> en général :\n              <ul>\n                <li><strong><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\"> / </span><span><span class=\"nc-blue_bg\">CRP</span></span></strong> : <span>syndrome inflammatoire</span> avec hyperleucocytose (non spécifique)</li>\n                <li><strong><span class=\"nc-purple_bg\">Prélèvement bactériologique de lait</span></strong> : recommandé</li>\n                <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> mammaire</span></strong> : si atypique, traînant, ou doute sur un <span>abcès</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microbiologie</strong></td>\n            <td>\n              <ul>\n                <li><strong>Prélèvement</strong> après toilette minutieuse du sein, sans prendre les 1<sup>ers</sup> mL extraits</li>\n                <li>Germes : <span><span class=\"nc-yellow_bg\">Staphylocoque doré</span></span> (le plus fréquent), <span><span class=\"nc-purple_bg\">E. coli</span></span>, <span><span class=\"nc-purple_bg\">Streptocoque B</span></span> (à envisager si <strong><span class=\"nc-red nc-bold\">mastite bilatérale</span></strong>)</li>\n                <li><strong>Interprétation</strong> : chez la femme en bonne santé, 10²–10⁵ germes dont <span>70 % de staph à coagulase −</span> ; en faveur d’une <span class=\"nc-red_bg\">mastite infectieuse</span> → <span <span=\"\">&gt;1</span> germe isolé <span>&gt; 10⁶/mL</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span><span class=\"nc-red nc-bold\">Abcès</span></span><span class=\"nc-red nc-bold\"> du sein</span> lactant</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"nc-yellow_bg\">Collection de pus </span><strong><span class=\"nc-yellow_bg\">bien délimitée</span></strong><span class=\"nc-yellow_bg\"> dans le sein</span>, <strong><span class=\"nc-red nc-bold\">complication de la mastite</span></strong></td></tr>\n          <tr><td><strong>Fréquence</strong></td><td><span>≈ 1 %</span> des femmes allaitant</td></tr>\n          <tr><td><strong>Délai</strong></td><td>Vers la <span><span class=\"nc-pink nc-bold\">6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> semaine</span></span> (mais peut survenir à tout moment de la lactation et au <span>sevrage</span>)</td></tr>\n          <tr><td><strong>Début</strong></td><td>Souvent insidieux, douleurs chroniques, tableau à bas bruit</td></tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <ul>\n                <li>Signes inflammatoires sévères : <span class=\"nc-red nc-bold\">douleur</span> <strong>pulsatile / insomniante</strong>, rougeur, chaleur, <span>œdème</span></li>\n                <li><span>Abcès</span> <strong>froid</strong> sans inflammation : plus rare</li>\n                <li><span><span class=\"nc-yellow_bg nc-bold\">Masse</span> <span class=\"nc-yellow_bg nc-bold\">fluctuante</span></span> avec changement de coloration cutanée <span><span class=\"nc-yellow_bg nc-bold\">rouge</span> <span class=\"nc-yellow_bg nc-bold\">violacé</span></span> <em>(fait la différence avec la mastite)</em></li>\n                <li><span><span class=\"nc-red nc-bold\">Nécrose cutanée possible</span></span></li>\n                <li><span><span class=\"nc-red nc-bold\">Fièvre</span></span> <strong>plus modérée</strong> que dans la mastite, <span class=\"nc-brown_bg\">voire absente</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\"> / </span><span><span class=\"nc-blue_bg\">CRP</span></span></strong> : <span>syndrome inflammatoire</span> avec hyperleucocytose, <span>CRP</span> élevée</li>\n                <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span></strong> (radiologue compétent en sénologie) : si doute (spécifique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Éviter toute stase de lait ; agir vite en cas d’engorgement, de canal bouché, de <span class=\"nc-blue_bg\">mamelon</span> <span class=\"nc-blue_bg nc-bold\">douloureux</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Insuffisance de lait (IL)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>IL primaire</strong><br><em>(exceptionnelle)</em></td>\n            <td>\n              Incapacité maternelle à produire du lait en quantité suffisante :\n              <ul>\n                <li>Origine <strong>hormonale</strong></li>\n                <li>Origine <strong><span class=\"nc-red nc-bold\">anatomique</span></strong> : <span><span class=\"nc-pink_bg\">chirurgie</span></span><span class=\"nc-pink_bg\"> esthétique</span> (prothèse mammaire, plastie de <span>réduction</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IL secondaire</strong><br><em>(principalement)</em></td>\n            <td>\n              <ol>\n                <li>Conduite inappropriée de l’AM (<span class=\"nc-yellow_bg\">tétées</span> <span class=\"nc-yellow_bg\">inefficaces</span> et/ou <span class=\"nc-yellow_bg\">trop peu nombreuses</span>)</li>\n                <li>Diminution du transfert de lait + de la sécrétion lactée (favorisée par la <strong><span class=\"nc-red nc-bold\">séparation mère/enfant</span></strong>)</li>\n              </ol>\n            </td>\n          </tr>\n          <tr><td><strong>Conséquence</strong></td><td><span><span class=\"nc-red_bg\">Principale cause d’</span>interruption précoce de l’AM</span></td></tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>\n              <em>Perception inappropriée d’IL = situation la plus fréquente</em>\n              <ul>\n                <li>Conseils / soutien pour restaurer la confiance maternelle</li>\n                <li><span class=\"nc-green_bg\">Mises au sein plus fréquentes pour stimuler la sécrétion lactée</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non efficace ❌</strong></td>\n            <td>Tire-lait, <span>dompéridone</span>, <span>métoclopramide</span>, oxytocine, galactologues à base de plantes : <span>aucune preuve d’efficacité</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pièges chez l’enfant.</strong> L’<span>ictère au <span class=\"nc-pink nc-bold\">lait maternel</span></span> <span class=\"nc-green_bg\">est</span> <strong>sans <span><span>critère de</span> gravité</span></strong> → <span>ne doit pas faire interrompre l’AM</span>. Les <strong>difficultés de succion</strong> (plus fréquentes chez l’immature) peuvent nécessiter l’utilisation temporaire d’un <span class=\"nc-green nc-bold\">tire-lait</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 158 — <span>Sepsis</span> et <span>choc septique</span> · 32 — Evaluation du nouveau-né</em></p></div>"},{"i":"e5060f1f956e","n":33,"o":"33-5","u":"Physiopathologie","t":"Connaître les mécanismes et les facteurs favorisant les complications de l’allaitement","q":"Que retenir concernant les mécanismes et les facteurs favorisant les complications de l’allaitement ?","a":"<div class=\"notion-course\"><h4>Mécanismes des complications</h4>\n\n      <table>\n        <thead>\n          <tr><th>Complication</th><th>Mécanisme principal</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Engorgement pathologique</strong></td>\n            <td>\n              <ul>\n                <li><span>Stase de lait</span> → ↑ pression intra-alvéolaire → blocage de l’écoulement du lait</li>\n                <li>Composante vasculaire associée : stase capillaire et lymphatique → <span>œdème</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Crevasses du <span class=\"nc-blue_bg\">mamelon</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Friction anormale</span> mamelon / bouche du bébé = mécanisme central</li>\n                <li><span>Évolution</span> : <span class=\"nc-red nc-bold\">douleur</span> → rougeur → fissure / <span>érosion</span> → saignement possible</li>\n                <li>Porte d’entrée potentielle pour <strong>S. aureus</strong> ou <strong>candidose</strong> → <span class=\"nc-red nc-bold\">mastite</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Mastite</span> / <span class=\"nc-purple nc-bold\">galactophorite</span></strong></td>\n            <td>\n              <ul>\n                <li>Mécanisme initial = <span><span class=\"nc-red nc-bold\">stase du lait</span></span> (engorgement non drainé)</li>\n                <li>Colonisation <span>bactérienne</span> secondaire : <span><span class=\"nc-yellow_bg\">Staphylocoque</span></span><span class=\"nc-yellow_bg\"> doré</span> (le + fréquent), <span class=\"nc-purple_bg\">E. coli</span>, Strepto B (si <strong>bilatérale</strong>)</li>\n                <li>Pus dans le lait = <strong><span class=\"nc-red nc-bold\">signe de Budin</span></strong> → <span class=\"nc-purple nc-bold\">galactophorite</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Abcès</span></span><span class=\"nc-red nc-bold\"> du sein</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Évolution</span> d’une <span>mastite non ou mal drainée</span> (suspendre l’AM expose à cette complication)</li>\n                <li>Constitution d’une collection purulente bien délimitée</li>\n                <li>Germes : <span><span class=\"nc-purple nc-bold\">staphylocoque</span></span><span class=\"nc-purple nc-bold\"> doré</span>, <span class=\"nc-purple nc-bold\">streptocoque A</span>, <span class=\"nc-purple nc-bold\">entérocoque</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Insuffisance de lait</strong></td>\n            <td>\n              <ul>\n                <li>Primaire (rare) : <span class=\"nc-red nc-bold\">hormonale</span> ou <span class=\"nc-red nc-bold\">anatomique</span> (<span>chirurgie</span> mammaire esthétique / <span>réduction</span>)</li>\n                <li>Secondaire (++) : conduite inappropriée de l’AM, <span class=\"nc-red nc-bold\">séparation mère/enfant</span> → ↓ stimulation neurohormonale → ↓ <span class=\"nc-pink nc-bold\">prolactine</span> / <span class=\"nc-pink nc-bold\">ocytocine</span> → ↓ production</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus — causes d’engorgement <em>(détaillé)</em></h4>\n\n      <table>\n        <thead>\n          <tr><th>Cause</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mauvaise technique d’<span>allaitement</span></strong></td>\n            <td>\n              <ul>\n                <li>Initiation retardée de l’AM à la naissance</li>\n                <li><span class=\"nc-red_bg\">Mauvaise prise du sein</span></li>\n                <li>Conséquences : extraction de lait inefficace, limitation arbitraire fréquence / durée des tétées, compléments, canal lactifère bouché</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-green_bg\">Engorgement physiologique</span></strong></td>\n            <td><span>Incidence</span> <span>−50 %</span> si les tétées se font à la demande de l’enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Obstruction d’un canal lactifère</strong></td>\n            <td>\n              Bouchon de <strong>caséine, lipides, substances solidifiées par sels calciques</strong> :\n              <ul>\n                <li><strong>Clinique</strong> : <span class=\"nc-blue nc-bold\">petit bouton </span><span><span class=\"nc-blue nc-bold\">blanc</span>, voire <span class=\"nc-blue nc-bold\">marron</span> ou <span class=\"nc-blue nc-bold\">verdâtre</span></span> sur le <span class=\"nc-blue_bg\">mamelon</span>, <span class=\"nc-blue_bg nc-bold\">douloureux</span>, engorgement du secteur du canal bouché</li>\n                <li><strong>CAT</strong> : <span class=\"nc-green_bg\">positionner le menton du bébé sur la zone indurée</span> pendant la tétée, éviter tout obstacle à l’écoulement (vêtements serrés), compresses chaudes humides, puis <span class=\"nc-green_bg\">massages doux</span> et retrait du bouchon si insuffisant</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs favorisant les complications</h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Pratique d’AM</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Mise au sein différée</span></li>\n                <li><span class=\"nc-red_bg\">Mauvaise prise du sein</span>, tétées limitées en fréquence ou durée</li>\n                <li>Compléments de lait artificiel en maternité</li>\n                <li><span>Sevrage</span> trop rapide ou trop brutal</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li>Crevasses pré-existantes (porte d’entrée infectieuse)</li>\n                <li>Mauvaise hygiène / défaut de <span class=\"nc-green_bg\">lavage des mains</span></li>\n                <li>Vêtements trop serrés (favorisent l’obstruction canalaire)</li>\n                <li>Antécédent de mastite (récidive si cause non corrigée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bébé</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red nc-bold\">Troubles de succion</span> (<span class=\"nc-red nc-bold\">frein de langue trop court</span> ++)</li>\n                <li>Prématurité, immaturité de la succion</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Anatomique</span></strong></td>\n            <td>\n              <ul>\n                <li>Anomalie d’un canal galactophore</li>\n                <li>Tumeur du sein sous-jacente (à évoquer si mastite récidivante toujours au même endroit)</li>\n                <li><span>Chirurgie</span> mammaire antérieure (prothèse, plastie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span><span class=\"nc-red nc-bold\">Stase du lait</span> + mauvaise technique d’AM = couple causal central</span> des 4 complications mammaires (engorgement → crevasses → <span class=\"nc-red nc-bold\">mastite</span> → <span>abcès</span>). La prévention efficace est <strong>la même</strong> partout : <span>drainage</span> du sein <strong>fréquent, efficace, sans restriction</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 31 — Accouchement - suites de couche normales</em></p></div>"},{"i":"c7542da14c08","n":33,"o":"33-6","u":"Prise en charge","t":"Allaitement et médicaments, infections et toxiques","q":"Que retenir concernant allaitement et médicaments, infections et toxiques ?","a":"<div class=\"notion-course\"><ul><li>Vérifier chaque médicament avec une source spécialisée (CRAT/RCP), en tenant compte de la dose, de la voie, de l’âge et de la prématurité de l’enfant. Une mention de prudence ne signifie pas automatiquement arrêt de l’allaitement.</li><li>Éviter alcool et drogues ; accompagner le sevrage tabagique et protéger l’enfant du <span class=\"nc-red_bg\">tabagisme</span> passif. Une difficulté de sevrage ne justifie pas une information culpabilisante ni une décision automatique sans discussion.</li><li>Les infections maternelles ne sont pas toutes des contre-indications : contexte, contagiosité et mesures de prévention propres à l’agent. Mastite habituelle : poursuite de l’allaitement généralement possible, avec traitement adapté.</li><li>VIH : selon HAS 2024, un allaitement peut être envisagé sous conditions strictes de contrôle virologique et de suivi spécialisé maternel–infantile, avec information sur le risque résiduel et la prophylaxie. Ce n’est ni une autorisation générale sans suivi, ni une interdiction universelle.</li><li>Lésion herpétique sur le sein : éviter le contact de l’enfant avec la lésion et le sein atteint jusqu’à guérison selon avis spécialisé ; le sein sain peut être utilisé avec précautions.</li><li>Prématurité, traitement cytotoxique ou situation infectieuse particulière : avis spécialisé et soutien d’une solution nutritionnelle sûre.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418192a2bac3ce6c64a558?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant","label":"HAS · Grossesse et VIH, 2024"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Souhait et situation de la mère/enfant","detail":"<ul><li>Information, bénéfices, soutien et respect du choix.</li></ul>","branches":[{"label":"Démarrage / question pratique","to":"observer"},{"label":"Douleur / fièvre / difficulté","to":"probleme"}]},{"id":"observer","kind":"decision","label":"Observer une tétée","detail":"<ul><li>Installation, prise du sein, succion, déglutition et signes d’apports suffisants.</li></ul>","branches":[{"label":"Transfert satisfaisant","to":"suivi"},{"label":"Inefficace / douleur","to":"aider"}]},{"id":"aider","kind":"decision","label":"Corriger la cause et protéger les apports","detail":"<ul><li>Aide qualifiée, expression si nécessaire, surveillance poids/hydratation.</li></ul>","branches":[{"label":"Réévaluer rapidement","to":"suivi"}]},{"id":"probleme","kind":"decision","label":"Quel signe domine ?","detail":"<ul><li>Examen du sein et état général ; évaluer aussi l’enfant.</li></ul>","branches":[{"label":"Fièvre / rougeur / masse","to":"infection"},{"label":"Crevasse / engorgement","to":"aider"},{"label":"Médicament / infection spécifique","to":"compat"}]},{"id":"infection","kind":"finish","label":"Mastite ou abcès ?","detail":"<ul><li>Traitement adapté, échographie/drainage si abcès ; ne pas interrompre automatiquement tout allaitement.</li></ul>","branches":[]},{"id":"compat","kind":"finish","label":"Vérifier le produit et le contexte","detail":"<ul><li>CRAT/RCP, prématurité et infection ; VIH selon suivi spécialisé HAS 2024.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Suivi mère–enfant et soutien","detail":"<ul><li>Poids, élimination, douleur, fatigue et besoins ; consulter si aggravation.</li></ul>","branches":[]}]}};
